#!/usr/bin/env python3
"""Official Binance PC6 immutable archive materializer.

Engineering only: this program enumerates, verifies, stores, and normalizes
official Binance monthly public-data objects.  It never computes returns,
portfolio statistics, rankings, or scientific verdicts.
"""

from __future__ import annotations

import argparse
import concurrent.futures as cf
import csv
import datetime as dt
import fcntl
import hashlib
import io
import json
import os
import re
import shutil
import sys
import tempfile
import time
import urllib.parse
import urllib.request
import xml.etree.ElementTree as ET
import zipfile
from collections import defaultdict
from pathlib import Path
from typing import Any, Iterable

S3 = "https://s3-ap-northeast-1.amazonaws.com/data.binance.vision"
PUBLIC = "https://data.binance.vision/"
FAPI_INFO = "https://fapi.binance.com/fapi/v1/exchangeInfo"
SPOT_INFO = "https://api.binance.com/api/v3/exchangeInfo"
START_MONTH = "2023-07"
START_US = 1688256000 * 1_000_000  # 2023-07-02T00:00:00Z
HOUR_US = 3600 * 1_000_000
SNAP_TOLERANCE_US = 72 * 1_000_000
USER_AGENT = "P5-PC6-Binance-Materializer/1"
HEX64 = re.compile(r"^[0-9a-f]{64}$")
MONTH_RE = re.compile(r"-(20\d{2}-\d{2})\.zip$")


def now_iso() -> str:
    return dt.datetime.now(dt.timezone.utc).isoformat(timespec="microseconds").replace("+00:00", "Z")


def iso_to_us(value: str | None) -> int | None:
    if not value:
        return None
    parsed = dt.datetime.fromisoformat(value.replace("Z", "+00:00"))
    return int(parsed.timestamp() * 1_000_000)


def http_date_to_iso(value: str | None) -> str | None:
    if not value:
        return None
    import email.utils
    parsed = email.utils.parsedate_to_datetime(value).astimezone(dt.timezone.utc)
    return parsed.isoformat(timespec="seconds").replace("+00:00", "Z")


def canonical_bytes(value: Any) -> bytes:
    return (json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False) + "\n").encode()


def sha_bytes(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def sha_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def atomic_write_once(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists():
        if path.read_bytes() != data:
            raise RuntimeError(f"WRITE_ONCE_CONFLICT:{path}")
        return
    fd, tmp = tempfile.mkstemp(prefix=".tmp-", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())
        try:
            os.link(tmp, path)
        except FileExistsError:
            if path.read_bytes() != data:
                raise RuntimeError(f"WRITE_ONCE_CONFLICT:{path}")
        finally:
            os.unlink(tmp)
    except Exception:
        if os.path.exists(tmp):
            os.unlink(tmp)
        raise


def atomic_update_pointer(path: Path, data: bytes) -> None:
    """Atomically update a navigation pointer; immutable revisions remain write-once."""
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(prefix=".pointer-", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, path)
    finally:
        if os.path.exists(tmp):
            os.unlink(tmp)


def canonicalize_http_url(url: str) -> str:
    parts = urllib.parse.urlsplit(url)
    return urllib.parse.urlunsplit((
        parts.scheme,
        parts.netloc.encode("idna").decode("ascii"),
        urllib.parse.quote(urllib.parse.unquote(parts.path), safe="/%:@"),
        parts.query,
        parts.fragment,
    ))


def fetch(url: str, timeout: int = 60) -> tuple[bytes, dict[str, str], int]:
    ascii_url = canonicalize_http_url(url)
    req = urllib.request.Request(ascii_url, headers={"User-Agent": USER_AGENT})
    with urllib.request.urlopen(req, timeout=timeout) as response:
        return response.read(), {k.lower(): v for k, v in response.headers.items()}, response.status


def list_s3(prefix: str, delimiter: str | None = None) -> tuple[list[dict[str, Any]], list[str]]:
    token = None
    objects: list[dict[str, Any]] = []
    prefixes: list[str] = []
    ns = {"s3": "http://s3.amazonaws.com/doc/2006-03-01/"}
    while True:
        params = {"list-type": "2", "prefix": prefix, "max-keys": "1000"}
        if delimiter:
            params["delimiter"] = delimiter
        if token:
            params["continuation-token"] = token
        data, _, _ = fetch(S3 + "?" + urllib.parse.urlencode(params), 90)
        root = ET.fromstring(data)
        for item in root.findall("s3:Contents", ns):
            objects.append({
                "key": item.findtext("s3:Key", namespaces=ns),
                "size": int(item.findtext("s3:Size", "0", ns)),
                "last_modified": item.findtext("s3:LastModified", namespaces=ns),
                "etag": (item.findtext("s3:ETag", "", ns) or "").strip('"'),
            })
        prefixes.extend(x.findtext("s3:Prefix", namespaces=ns) for x in root.findall("s3:CommonPrefixes", ns))
        if root.findtext("s3:IsTruncated", "false", ns) != "true":
            break
        token = root.findtext("s3:NextContinuationToken", namespaces=ns)
        if not token:
            raise RuntimeError("S3_TRUNCATED_WITHOUT_TOKEN")
    return objects, prefixes


def month_range(start: str, end: str) -> list[str]:
    y, m = map(int, start.split("-")); ey, em = map(int, end.split("-"))
    out = []
    while (y, m) <= (ey, em):
        out.append(f"{y:04d}-{m:02d}")
        m += 1
        if m == 13: y, m = y + 1, 1
    return out


def month_end_us(month: str) -> int:
    y, m = map(int, month.split("-"))
    if m == 12: nxt = dt.datetime(y + 1, 1, 1, tzinfo=dt.timezone.utc)
    else: nxt = dt.datetime(y, m + 1, 1, tzinfo=dt.timezone.utc)
    return int(nxt.timestamp() * 1_000_000)


def object_month(key: str) -> str | None:
    m = MONTH_RE.search(key)
    return m.group(1) if m else None


def dataset_prefix(dataset: str, symbol: str) -> str:
    if dataset == "futures_1h":
        return f"data/futures/um/monthly/klines/{symbol}/1h/"
    if dataset == "spot_1h":
        return f"data/spot/monthly/klines/{symbol}/1h/"
    if dataset == "funding":
        return f"data/futures/um/monthly/fundingRate/{symbol}/"
    raise ValueError(dataset)


def list_dataset_symbol(args: tuple[str, str, str]) -> tuple[str, str, list[dict[str, Any]]]:
    dataset, symbol, max_month = args
    objects, _ = list_s3(dataset_prefix(dataset, symbol))
    by_key = {x["key"]: x for x in objects}
    selected = []
    for obj in objects:
        month = object_month(obj["key"])
        if not month or not (START_MONTH <= month <= max_month):
            continue
        checksum = by_key.get(obj["key"] + ".CHECKSUM")
        row = dict(obj)
        row.update({"dataset": dataset, "symbol": symbol, "month": month,
                    "checksum_object": checksum})
        selected.append(row)
    return dataset, symbol, selected


def metadata_snapshot(url: str) -> tuple[dict[str, Any], dict[str, Any]]:
    retrieved = now_iso()
    data, headers, status = fetch(url, 90)
    return json.loads(data), {
        "url": url, "retrieved_at": retrieved, "http_status": status,
        "http_headers": {k: headers.get(k) for k in ("content-length", "last-modified", "etag")},
        "raw_sha256": sha_bytes(data), "raw_byte_size": len(data), "raw_bytes": data,
    }


def prior_latest(root: Path) -> dict[str, dict[str, Any]]:
    latest: dict[str, dict[str, Any]] = {}
    revision_dir = root / "raw" / "revisions"
    if not revision_dir.exists(): return latest
    for path in sorted(revision_dir.glob("*.json")):
        row = json.loads(path.read_text())
        old = latest.get(row["remote_object_identity"])
        if old is None or old["retrieval_timestamp"] < row["retrieval_timestamp"]:
            latest[row["remote_object_identity"]] = row
    return latest


def parent_revision_id(latest: dict[str, dict[str, Any]], identity: str,
                       new_sha256: str) -> str | None:
    previous = latest.get(identity)
    if previous is None or previous.get("raw_sha256") == new_sha256:
        return None
    return previous.get("revision_id")


def prior_completed_utc_day_quote_volume(rows: Iterable[dict[str, Any]],
                                         decision_time_us: int) -> float:
    decision = dt.datetime.fromtimestamp(decision_time_us / 1_000_000, tz=dt.timezone.utc)
    day_start = dt.datetime(decision.year, decision.month, decision.day, tzinfo=dt.timezone.utc)
    start_us = int((day_start - dt.timedelta(days=1)).timestamp() * 1_000_000)
    end_us = int(day_start.timestamp() * 1_000_000)
    values = [float(row["quote_volume"]) for row in rows
              if start_us <= int(row["close_time_us"]) < end_us]
    return sum(values)


def fixed_common_clock_8h_us(start_us: int,
                              funding_events: Iterable[dict[str, Any]]) -> dict[str, Any]:
    if start_us % HOUR_US:
        raise RuntimeError("FIXED_8H_ANCHOR_NOT_FULL_UTC_HOUR")
    end_us=start_us+8*HOUR_US
    events=[row for row in funding_events
            if start_us <= int(row["market_event_time_us"]) < end_us]
    return {"holding_semantics":"FIXED_COMMON_CLOCK_8H","timestamp_unit":"epoch_us",
            "start_us":start_us,"end_us":end_us,"duration_us":8*HOUR_US,
            "funding_events":events,"funding_event_count":len(events)}


def actual_settlement_to_settlement_us(
        funding_events: Iterable[dict[str, Any]]) -> list[dict[str, Any]]:
    events=sorted(funding_events,key=lambda x:int(x["market_event_time_us"]))
    out=[]
    for left,right in zip(events,events[1:]):
        start=int(left["market_event_time_us"]); end=int(right["market_event_time_us"])
        if end <= start: raise RuntimeError("NON_MONOTONIC_FUNDING_EVENTS")
        raw_duration=end-start
        declared=float(left["funding_interval_hours"])
        declared_us=round(declared*HOUR_US)
        if abs(raw_duration-declared_us)>SNAP_TOLERANCE_US:
            raise RuntimeError("FUNDING_INTERVAL_EXCEEDS_SNAP_TOLERANCE")
        out.append({"holding_semantics":"ACTUAL_SETTLEMENT_TO_SETTLEMENT",
                    "timestamp_unit":"epoch_us","start_us":start,"end_us":end,
                    "raw_duration_us":raw_duration,"snapped_interval_hours":declared,
                    "realized_funding_events":[left]})
    return out


def write_snapshot(root: Path, source: dict[str, Any], identity: str, namespace: str) -> dict[str, Any]:
    data = source.pop("raw_bytes")
    actual = source["raw_sha256"]
    blob = root / "raw" / "blobs" / "sha256" / actual[:2] / actual
    atomic_write_once(blob, data)
    rid = f"rev-{dt.datetime.now(dt.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')}-{actual[:16]}"
    old = prior_latest(root).get(identity)
    row = {
        "revision_id": rid, "parent_revision_id": parent_revision_id(prior_latest(root), identity, actual),
        "source_provider": "Binance", "source_namespace": namespace,
        "remote_object_identity": identity, "archive_class": "LIVE_OFFICIAL_METADATA_SNAPSHOT",
        "retrieval_timestamp": source["retrieved_at"], "raw_sha256": actual,
        "raw_byte_size": len(data), "raw_storage_locator": str(blob),
        "official_checksum": None, "checksum_status": "NOT_PUBLISHED_FOR_LIVE_METADATA",
        "http_metadata": source["http_headers"], "source_url": source["url"],
    }
    atomic_write_once(root / "raw" / "revisions" / f"{rid}.json", canonical_bytes(row))
    return row


def direct_identity_map(futures_symbols: list[dict[str, Any]], spot_symbols: list[dict[str, Any]],
                        archive_symbols: set[str], spot_archive_symbols: set[str]) -> list[dict[str, Any]]:
    spot = {x["symbol"]: x for x in spot_symbols}
    current_futures = {x["symbol"]: x for x in futures_symbols}
    rows = []
    for symbol in sorted(archive_symbols):
        f = current_futures.get(symbol)
        s = spot.get(symbol)
        base = {
            "perp_symbol": symbol, "futures_pair": f.get("pair") if f else None,
            "contractType": f.get("contractType") if f else None,
            "futures_baseAsset": f.get("baseAsset") if f else None,
            "futures_quoteAsset": f.get("quoteAsset") if f else None,
            "marginAsset": f.get("marginAsset") if f else None,
            "underlyingType": f.get("underlyingType") if f else None,
            "underlyingSubType": f.get("underlyingSubType") if f else None,
            "futures_status": f.get("status") if f else None,
            "onboardDate_metadata_ms": f.get("onboardDate") if f else None,
            "deliveryDate_metadata_ms": f.get("deliveryDate") if f else None,
            "spot_symbol": symbol if s else None,
            "spot_baseAsset": s.get("baseAsset") if s else None,
            "spot_quoteAsset": s.get("quoteAsset") if s else None,
            "price_unit_multiplier": None, "contract_unit_semantics": None,
            "mapping_source": [FAPI_INFO, SPOT_INFO, "OFFICIAL_ARCHIVE_NAMESPACE"],
            "mapping_confidence": "FAIL_CLOSED",
        }
        status = "UNRESOLVED_IDENTITY"
        reasons = []
        if not f:
            reasons.append("ABSENT_FROM_CURRENT_OFFICIAL_FUTURES_METADATA")
        elif f.get("contractType") != "PERPETUAL":
            status = "INCOMPATIBLE"; reasons.append("NOT_PERPETUAL")
        elif f.get("quoteAsset") != "USDT" or f.get("marginAsset") != "USDT":
            status = "INCOMPATIBLE"; reasons.append("NOT_USDT_LINEAR_SCOPE")
        elif f.get("underlyingType") not in (None, "COIN"):
            status = "INCOMPATIBLE"; reasons.append("NON_CRYPTO_UNDERLYING")
        elif not s or symbol not in spot_archive_symbols:
            status = "NO_SPOT_PAIR"; reasons.append("NO_OFFICIAL_SPOT_METADATA_OR_ARCHIVE")
        elif s.get("baseAsset") != f.get("baseAsset") or s.get("quoteAsset") != f.get("quoteAsset"):
            status = "UNRESOLVED_UNIT_MAPPING"; reasons.append("BASE_OR_QUOTE_ASSET_MISMATCH")
        elif f.get("pair") != symbol:
            status = "UNRESOLVED_IDENTITY"; reasons.append("FUTURES_PAIR_NOT_SYMBOL")
        else:
            status = "VERIFIED_UNIT_COMPATIBLE"
            base["price_unit_multiplier"] = "1"
            base["contract_unit_semantics"] = "ONE_FUTURES_BASE_PRICE_UNIT_EQUALS_ONE_SPOT_BASE_PRICE_UNIT"
            base["mapping_confidence"] = "OFFICIAL_METADATA_DIRECT_MATCH"
        base["status"] = status
        base["exclusion_reasons"] = reasons
        rows.append(base)
    return rows


def enumerate_plan(root: Path, max_workers: int) -> dict[str, Any]:
    retrieved = now_iso()
    f_info, f_source = metadata_snapshot(FAPI_INFO)
    s_info, s_source = metadata_snapshot(SPOT_INFO)
    f_rev = write_snapshot(root, f_source, FAPI_INFO, "FAPI_EXCHANGE_INFO")
    s_rev = write_snapshot(root, s_source, SPOT_INFO, "SPOT_EXCHANGE_INFO")
    _, f_prefixes = list_s3("data/futures/um/monthly/klines/", "/")
    _, s_prefixes = list_s3("data/spot/monthly/klines/", "/")
    f_symbols = {x.rstrip("/").split("/")[-1] for x in f_prefixes}
    s_symbols = {x.rstrip("/").split("/")[-1] for x in s_prefixes}

    previous_month = (dt.datetime.now(dt.timezone.utc).replace(day=1) - dt.timedelta(days=1)).strftime("%Y-%m")
    probe_symbols = ["BTCUSDT"]
    common_max = previous_month
    for ds in ("futures_1h", "spot_1h", "funding"):
        _, _, rows = list_dataset_symbol((ds, "BTCUSDT", previous_month))
        months = sorted(x["month"] for x in rows if x["checksum_object"])
        if not months: raise RuntimeError(f"NO_OFFICIAL_MONTHLY_ARCHIVE:{ds}:BTCUSDT")
        common_max = min(common_max, months[-1])
    max_month = common_max

    identity = direct_identity_map(f_info["symbols"], s_info["symbols"], f_symbols, s_symbols)
    verified = sorted(x["perp_symbol"] for x in identity if x["status"] == "VERIFIED_UNIT_COMPATIBLE")
    if not verified: raise RuntimeError("NO_VERIFIED_UNIT_COMPATIBLE_IDENTITIES")

    tasks = [(ds, symbol, max_month) for symbol in verified for ds in ("futures_1h", "spot_1h", "funding")]
    objects: list[dict[str, Any]] = []
    with cf.ThreadPoolExecutor(max_workers=max_workers) as ex:
        for _, _, rows in ex.map(list_dataset_symbol, tasks): objects.extend(rows)

    object_idx = {(x["dataset"], x["symbol"], x["month"]): x for x in objects}
    expected_months = month_range(START_MONTH, max_month)
    gaps = []
    executable_cells = []
    for symbol in verified:
        present = {ds: {m for d, s, m in object_idx if d == ds and s == symbol and object_idx[(d,s,m)]["checksum_object"]}
                   for ds in ("futures_1h", "spot_1h", "funding")}
        first = min(present["futures_1h"]) if present["futures_1h"] else None
        for month in expected_months:
            if first and month >= first:
                for ds in present:
                    if month not in present[ds]: gaps.append({"symbol": symbol, "month": month, "dataset": ds,
                                                               "classification": "SOURCE_ARCHIVE_GAP"})
            if all(month in present[ds] for ds in present):
                executable_cells.append({"symbol": symbol, "month": month})

    selected = [x for x in objects if x["checksum_object"]]
    raw_bytes = sum(x["size"] + x["checksum_object"]["size"] for x in selected)
    stat = shutil.disk_usage(root.parent)
    capacity = {
        "raw_zip_and_checksum_bytes": raw_bytes,
        "normalized_projected_upper_bound_bytes": raw_bytes * 8,
        "total_projected_upper_bound_bytes": raw_bytes * 9,
        "available_bytes": stat.free,
        "capacity_gate": "PASS" if stat.free > raw_bytes * 9 else "FAIL",
    }
    if capacity["capacity_gate"] != "PASS": raise RuntimeError("INSUFFICIENT_STORAGE")
    # Remove nested checksum object aliases before canonical serialization.
    for x in selected:
        c = x.pop("checksum_object")
        x["checksum_key"] = c["key"]
        x["checksum_size"] = c["size"]
        x["checksum_last_modified"] = c["last_modified"]
        x["checksum_etag"] = c["etag"]
        x["source_url"] = PUBLIC + x["key"]
        x["checksum_url"] = PUBLIC + x["checksum_key"]
    plan = {
        "canonical_id": "P5_PC6_BINANCE_ARCHIVE_ENUMERATION_V1",
        "generated_at": retrieved, "start_time_us": START_US,
        "start_month": START_MONTH, "engineering_max_available_month": max_month,
        "official_provider": "Binance", "archive_class": "MONTHLY",
        "futures_archive_identity_count": len(f_symbols),
        "spot_archive_identity_count": len(s_symbols),
        "verified_unit_compatible_identity_count": len(verified),
        "verified_symbols": verified, "objects": sorted(selected, key=lambda x: x["key"]),
        "source_archive_gaps": gaps, "executable_cells": executable_cells,
        "identity_map": identity, "capacity": capacity,
        "metadata_revision_ids": [f_rev["revision_id"], s_rev["revision_id"]],
    }
    plan["sha256"] = sha_bytes(canonical_bytes(plan))
    atomic_write_once(root / "plans" / f"enumeration-{plan['sha256']}.json", canonical_bytes(plan))
    atomic_update_pointer(root / "plans" / "CURRENT", (plan["sha256"] + "\n").encode())
    print(json.dumps({k: plan[k] for k in ("sha256", "engineering_max_available_month",
          "futures_archive_identity_count", "spot_archive_identity_count", "verified_unit_compatible_identity_count")}, indent=2))
    print(json.dumps(capacity, indent=2))
    print("OBJECTS", len(selected), "GAPS", len(gaps), "EXECUTABLE_CELLS", len(executable_cells))
    return plan


def load_plan(root: Path) -> dict[str, Any]:
    digest = (root / "plans" / "CURRENT").read_text().strip()
    return json.loads((root / "plans" / f"enumeration-{digest}.json").read_text())


def parse_checksum(data: bytes, expected_filename: str) -> str:
    text = data.decode("utf-8").strip()
    parts = text.split()
    if len(parts) != 2 or parts[1] != expected_filename or not HEX64.fullmatch(parts[0]):
        raise RuntimeError(f"CHECKSUM_SCHEMA_INVALID:{expected_filename}:{text!r}")
    return parts[0]


def download_one(args: tuple[Path, dict[str, Any], dict[str, dict[str, Any]]]) -> dict[str, Any]:
    root, obj, latest = args
    checksum_bytes, checksum_headers, c_status = fetch(obj["checksum_url"], 90)
    expected = parse_checksum(checksum_bytes, Path(obj["key"]).name)
    parent = latest.get(obj["key"])
    if (parent and parent.get("raw_sha256") == expected
            and parent.get("checksum_status") == "VERIFIED_SHA256"
            and Path(parent.get("raw_storage_locator", "")).is_file()
            and sha_file(Path(parent["raw_storage_locator"])) == expected):
        return parent
    zip_bytes, zip_headers, z_status = fetch(obj["source_url"], 180)
    actual = sha_bytes(zip_bytes)
    if actual != expected:
        raise RuntimeError(f"CHECKSUM_MISMATCH:{obj['key']}:{expected}:{actual}")
    if len(zip_bytes) != obj["size"]:
        raise RuntimeError(f"CONTENT_LENGTH_CONFLICT:{obj['key']}:{obj['size']}:{len(zip_bytes)}")
    try:
        with zipfile.ZipFile(io.BytesIO(zip_bytes)) as z:
            bad = z.testzip()
            if bad: raise RuntimeError(f"ZIP_CRC_FAILURE:{obj['key']}:{bad}")
            names = z.namelist()
            if len(names) != 1 or not names[0].endswith(".csv"):
                raise RuntimeError(f"ZIP_MEMBER_SCHEMA:{obj['key']}:{names}")
    except zipfile.BadZipFile as e:
        raise RuntimeError(f"ZIP_INVALID:{obj['key']}") from e
    blob = root / "raw" / "blobs" / "sha256" / actual[:2] / actual
    atomic_write_once(blob, zip_bytes)
    csha = sha_bytes(checksum_bytes)
    cblob = root / "raw" / "blobs" / "sha256" / csha[:2] / csha
    atomic_write_once(cblob, checksum_bytes)
    retrieved = now_iso()
    rid = f"rev-{dt.datetime.now(dt.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')}-{actual[:16]}"
    row = {
        "revision_id": rid, "parent_revision_id": parent_revision_id(latest, obj["key"], actual),
        "source_provider": "Binance", "source_namespace": obj["key"].rsplit("/",1)[0] + "/",
        "remote_object_identity": obj["key"], "source_url": obj["source_url"],
        "request_identity": {"method": "GET", "url": obj["source_url"]},
        "archive_class": "MONTHLY", "dataset": obj["dataset"], "symbol": obj["symbol"],
        "market": "USD_M_FUTURES" if obj["dataset"] != "spot_1h" else "SPOT",
        "interval": "1h" if obj["dataset"] != "funding" else "ACTUAL_SETTLEMENT",
        "year_month": obj["month"], "retrieval_timestamp": retrieved,
        "http_metadata": {"status": z_status, "content_length": zip_headers.get("content-length"),
                          "last_modified": zip_headers.get("last-modified"), "etag": zip_headers.get("etag")},
        "source_published_at": http_date_to_iso(zip_headers.get("last-modified")),
        "official_checksum_url": obj["checksum_url"], "official_checksum_sha256": expected,
        "official_checksum_raw_sha256": csha, "official_checksum_storage_locator": str(cblob),
        "checksum_http_status": c_status, "checksum_http_metadata": checksum_headers,
        "raw_sha256": actual, "raw_byte_size": len(zip_bytes), "raw_storage_locator": str(blob),
        "checksum_status": "VERIFIED_SHA256", "transform_code_identity": None,
        "transform_code_sha256": None, "normalized_output_locator": None,
        "normalized_output_sha256": None,
    }
    atomic_write_once(root / "raw" / "revisions" / f"{rid}.json", canonical_bytes(row))
    return row


def download_plan(root: Path, max_workers: int) -> list[dict[str, Any]]:
    plan = load_plan(root)
    latest = prior_latest(root)
    results = []
    failures = []
    args = [(root, x, latest) for x in plan["objects"]]
    with cf.ThreadPoolExecutor(max_workers=max_workers) as ex:
        futures = {ex.submit(download_one, a): a[1] for a in args}
        for n, fut in enumerate(cf.as_completed(futures), 1):
            obj = futures[fut]
            try: results.append(fut.result())
            except Exception as e: failures.append({"key": obj["key"], "error": repr(e)})
            if n % 500 == 0: print("DOWNLOAD_PROGRESS", n, "OF", len(args), "FAIL", len(failures), flush=True)
    summary = {
        "canonical_id": "P5_PC6_BINANCE_DOWNLOAD_RESULT_V1", "generated_at": now_iso(),
        "plan_sha256": plan["sha256"], "objects_planned": len(args), "objects_succeeded": len(results),
        "objects_failed": len(failures), "failures": failures,
        "raw_zip_bytes": sum(x["raw_byte_size"] for x in results),
    }
    summary["sha256"] = sha_bytes(canonical_bytes(summary))
    atomic_write_once(root / "download_results" / f"result-{summary['sha256']}.json", canonical_bytes(summary))
    atomic_update_pointer(root / "download_results" / "CURRENT", (summary["sha256"] + "\n").encode())
    print(json.dumps({k: summary[k] for k in ("objects_planned","objects_succeeded","objects_failed","raw_zip_bytes","sha256")}, indent=2))
    if failures: raise RuntimeError(f"DOWNLOAD_FAILURES:{len(failures)}")
    return results


def revision_index(root: Path) -> dict[str, dict[str, Any]]:
    return prior_latest(root)


def load_csv_from_revision(rev: dict[str, Any]) -> tuple[list[str] | None, list[list[str]]]:
    raw = Path(rev["raw_storage_locator"]).read_bytes()
    with zipfile.ZipFile(io.BytesIO(raw)) as z:
        with z.open(z.namelist()[0]) as f:
            text = io.TextIOWrapper(f, encoding="utf-8", newline="")
            rows = list(csv.reader(text))
    if not rows: return None, []
    first = rows[0]
    if first and first[0] in ("open_time", "calc_time"):
        return first, rows[1:]
    return None, rows


def normalize_timestamp(raw: int, dataset: str, month: str) -> int:
    if dataset == "spot_1h":
        if month < "2025-01":
            if not 1_000_000_000_000 <= raw < 10_000_000_000_000: raise RuntimeError("SPOT_PRE2025_UNIT")
            return raw * 1000
        if not 1_000_000_000_000_000 <= raw < 10_000_000_000_000_000: raise RuntimeError("SPOT_POST2025_UNIT")
        return raw
    if not 1_000_000_000_000 <= raw < 10_000_000_000_000: raise RuntimeError("FUTURES_TIMESTAMP_UNIT")
    return raw * 1000


def normalize_revision(root: Path, rev: dict[str, Any], code_sha: str) -> dict[str, Any]:
    import pandas as pd
    dataset, month, symbol = rev["dataset"], rev["year_month"], rev["symbol"]
    header, rows = load_csv_from_revision(rev)
    ingested_us = iso_to_us(rev["retrieval_timestamp"])
    published_us = iso_to_us(rev.get("source_published_at"))
    out = []
    if dataset in ("futures_1h", "spot_1h"):
        expected = ["open_time","open","high","low","close","volume","close_time","quote_volume",
                    "count","taker_buy_volume","taker_buy_quote_volume","ignore"]
        if header is not None and header != expected: raise RuntimeError(f"KLINE_HEADER:{header}")
        for r in rows:
            if len(r) != 12: raise RuntimeError(f"KLINE_WIDTH:{len(r)}")
            open_us = normalize_timestamp(int(r[0]), dataset, month)
            close_us = normalize_timestamp(int(r[6]), dataset, month)
            out.append({
                "venue":"BINANCE", "market":"USD_M_FUTURES" if dataset=="futures_1h" else "SPOT",
                "dataset":dataset, "symbol":symbol, "month":month,
                "raw_open_time":r[0], "raw_close_time":r[6], "market_event_time_us":close_us,
                "market_observable_at_us":close_us + 1, "p5_ingested_at_us":ingested_us,
                "revision_known_at_us":ingested_us, "source_published_at_us":published_us,
                "open_time_us":open_us, "close_time_us":close_us,
                "open_raw":r[1], "high_raw":r[2], "low_raw":r[3], "close_raw":r[4],
                "volume_raw":r[5], "quote_volume_raw":r[7], "trade_count":int(r[8]),
                "open":float(r[1]), "high":float(r[2]), "low":float(r[3]), "close":float(r[4]),
                "volume":float(r[5]), "quote_volume":float(r[7]),
                "source_revision_id":rev["revision_id"], "source_raw_sha256":rev["raw_sha256"],
                "in_engineering_window":open_us >= START_US,
            })
        keys=[(x["symbol"],x["open_time_us"]) for x in out]
    else:
        expected = ["calc_time","funding_interval_hours","last_funding_rate"]
        if header != expected: raise RuntimeError(f"FUNDING_HEADER:{header}")
        for r in rows:
            if len(r) != 3: raise RuntimeError(f"FUNDING_WIDTH:{len(r)}")
            event_us = normalize_timestamp(int(r[0]), "funding", month)
            out.append({
                "venue":"BINANCE", "market":"USD_M_FUTURES", "dataset":"funding", "symbol":symbol,
                "month":month, "raw_calc_time":r[0], "market_event_time_us":event_us,
                "market_observable_at_us":None, "p5_ingested_at_us":ingested_us,
                "revision_known_at_us":ingested_us, "source_published_at_us":published_us,
                "funding_interval_hours":float(r[1]), "funding_rate_raw":r[2],
                "funding_rate":float(r[2]), "source_revision_id":rev["revision_id"],
                "source_raw_sha256":rev["raw_sha256"], "in_engineering_window":event_us >= START_US,
            })
        keys=[(x["symbol"],x["market_event_time_us"]) for x in out]
    if len(keys) != len(set(keys)): raise RuntimeError(f"DUPLICATE_KEYS:{rev['remote_object_identity']}")
    import pyarrow as pa, pyarrow.parquet as pq
    table = pa.Table.from_pylist(out)
    temp_dir = root / "normalized" / "tmp"; temp_dir.mkdir(parents=True, exist_ok=True)
    fd, temp_name = tempfile.mkstemp(prefix="norm-", suffix=".parquet", dir=temp_dir); os.close(fd)
    temp = Path(temp_name)
    try:
        pq.write_table(table, temp, compression="zstd", use_dictionary=False,
                       write_statistics=True, version="2.6")
        digest = sha_file(temp)
        dest = root / "normalized" / "blobs" / "sha256" / digest[:2] / f"{digest}.parquet"
        dest.parent.mkdir(parents=True, exist_ok=True)
        if dest.exists():
            if sha_file(dest) != digest: raise RuntimeError("NORMALIZED_BLOB_CONFLICT")
        else:
            os.link(temp, dest)
        result = {
            "source_revision_id":rev["revision_id"], "source_raw_sha256":rev["raw_sha256"],
            "remote_object_identity":rev["remote_object_identity"], "dataset":dataset,
            "symbol":symbol, "month":month, "row_count":len(out),
            "normalized_output_locator":str(dest), "normalized_output_sha256":digest,
            "normalized_byte_size":dest.stat().st_size,
            "transform_code_identity":"git:k3/p5-codex-pc6-binance-data-materialization-v1:quant/p5_track3/binance_materializer.py",
            "transform_code_sha256":code_sha,
            "first_market_event_time_us":min((x["market_event_time_us"] for x in out),default=None),
            "last_market_event_time_us":max((x["market_event_time_us"] for x in out),default=None),
        }
        result["normalization_record_sha256"] = sha_bytes(canonical_bytes(result))
        atomic_write_once(root / "normalized" / "revisions" / f"{result['normalization_record_sha256']}.json",
                          canonical_bytes(result))
        return result
    finally:
        temp.unlink(missing_ok=True)


def normalize_all(root: Path, code_path: Path, max_workers: int) -> list[dict[str, Any]]:
    plan=load_plan(root); latest=revision_index(root); code_sha=sha_file(code_path)
    existing_by_source={x["source_revision_id"]:x for x in load_normalizations(root)}
    revisions=[]
    missing=[]
    for obj in plan["objects"]:
        rev=latest.get(obj["key"])
        if not rev or rev.get("checksum_status") != "VERIFIED_SHA256": missing.append(obj["key"])
        else:
            existing=existing_by_source.get(rev["revision_id"])
            if (existing and Path(existing.get("normalized_output_locator", "")).is_file()
                    and sha_file(Path(existing["normalized_output_locator"])) == existing.get("normalized_output_sha256")):
                continue
            revisions.append(rev)
    if missing: raise RuntimeError(f"RAW_REVISIONS_MISSING:{len(missing)}")
    results=[]; failures=[]; exclusions=[]
    with cf.ThreadPoolExecutor(max_workers=max_workers) as ex:
        futures={ex.submit(normalize_revision,root,rev,code_sha):rev for rev in revisions}
        for n,fut in enumerate(cf.as_completed(futures),1):
            try: results.append(fut.result())
            except Exception as e:
                item={"key":futures[fut]["remote_object_identity"],"error":repr(e)}
                if "DUPLICATE_KEYS:" in str(e):
                    item["classification"]="SOURCE_ARCHIVE_CONFLICT"
                    item["disposition"]="EXCLUDED_AFFECTED_SYMBOL_MONTH; RAW_PRESERVED_UNCHANGED"
                    exclusions.append(item)
                    conflict_sha=sha_bytes(canonical_bytes(item))
                    atomic_write_once(root/"normalized"/"conflicts"/f"{conflict_sha}.json",canonical_bytes(item))
                else:
                    failures.append(item)
            if n % 500 == 0: print("NORMALIZE_PROGRESS",n,"OF",len(revisions),"FAIL",len(failures),flush=True)
    summary={"canonical_id":"P5_PC6_BINANCE_NORMALIZATION_RESULT_V1","generated_at":now_iso(),
             "plan_sha256":plan["sha256"],"objects_planned":len(revisions),"objects_succeeded":len(results),
             "objects_failed":len(failures),"failures":failures,
             "objects_excluded":len(exclusions),"exclusions":exclusions,
             "normalized_bytes":sum(x["normalized_byte_size"] for x in results),"transform_code_sha256":code_sha}
    summary["sha256"]=sha_bytes(canonical_bytes(summary))
    atomic_write_once(root/"normalization_results"/f"result-{summary['sha256']}.json",canonical_bytes(summary))
    atomic_update_pointer(root/"normalization_results"/"CURRENT",(summary["sha256"]+"\n").encode())
    print(json.dumps({k:summary[k] for k in ("objects_planned","objects_succeeded","objects_failed","normalized_bytes","sha256")},indent=2))
    if failures: raise RuntimeError(f"NORMALIZATION_FAILURES:{len(failures)}")
    return results


def load_normalizations(root: Path) -> list[dict[str, Any]]:
    return [json.loads(p.read_text()) for p in sorted((root/"normalized"/"revisions").glob("*.json"))]


def load_normalization_conflicts(root: Path) -> dict[str, dict[str, Any]]:
    return {x["key"]:x for x in (json.loads(p.read_text()) for p in sorted((root/"normalized"/"conflicts").glob("*.json")))}


def artifact(root: Path, out_dir: Path, name: str, value: dict[str, Any]) -> tuple[Path,str]:
    value=dict(value); value["canonical_id"]=name
    data=canonical_bytes(value); actual=sha_bytes(data)
    # Hash is over exact final payload, and is the externally reported artifact hash.
    path=out_dir/f"{name}.json"; atomic_write_once(path,data)
    return path,actual


def build_artifacts(root: Path, out_dir: Path, code_path: Path) -> dict[str, Any]:
    plan=load_plan(root); norms=load_normalizations(root); latest=revision_index(root)
    build_git_commit=os.environ.get("P5_BUILD_GIT_COMMIT")
    if not build_git_commit or not re.fullmatch(r"[0-9a-f]{40}",build_git_commit):
        raise RuntimeError("P5_BUILD_GIT_COMMIT_REQUIRED")
    build_code_identity={"git_commit":build_git_commit,"file_sha256":sha_file(code_path),
                         "path":"quant/p5_track3/binance_materializer.py"}
    plan_file=root/"plans"/f"enumeration-{(root/'plans'/'CURRENT').read_text().strip()}.json"
    conflicts=load_normalization_conflicts(root)
    norm_idx={(x["dataset"],x["symbol"],x["month"]):x for x in norms}
    metadata_revisions=[]
    for rid in plan["metadata_revision_ids"]:
        metadata_revisions.append(json.loads((root/"raw"/"revisions"/f"{rid}.json").read_text()))
    fapi_revision=next(x for x in metadata_revisions if x["remote_object_identity"]==FAPI_INFO)
    fapi_payload=json.loads(Path(fapi_revision["raw_storage_locator"]).read_bytes())
    current_futures={x["symbol"]:x for x in fapi_payload["symbols"]}
    identity_rows=[]
    for source_row in plan["identity_map"]:
        row=dict(source_row); current=current_futures.get(row["perp_symbol"],{})
        row.update({"futures_status":current.get("status"),
                    "onboardDate_metadata_ms":current.get("onboardDate"),
                    "deliveryDate_metadata_ms":current.get("deliveryDate")})
        identity_rows.append(row)
    mapped=[x for x in identity_rows if x["status"]=="VERIFIED_UNIT_COMPATIBLE"]
    mapping_source_hashes=[]
    for rid in plan["metadata_revision_ids"]:
        r=json.loads((root/"raw"/"revisions"/f"{rid}.json").read_text()); mapping_source_hashes.append(r["raw_sha256"])
    identity_payload={"generated_at":now_iso(),"mapping_source_hashes":mapping_source_hashes,
                      "admission_statuses":["VERIFIED_UNIT_COMPATIBLE","VERIFIED_WITH_NORMALIZATION"],
                      "rows":identity_rows}
    identity_path,identity_sha=artifact(root,out_dir,"P5_P3_PERP_SPOT_IDENTITY_MAP_V1",identity_payload)

    by_symbol=defaultdict(list)
    for n in norms: by_symbol[n["symbol"]].append(n)
    episodes=[]
    for row in identity_rows:
        symbol=row["perp_symbol"]
        frows=sorted((x for x in by_symbol[symbol] if x["dataset"]=="futures_1h"),key=lambda x:x["month"])
        if not frows: continue
        import pyarrow.parquet as pq
        positive_times=[]
        for normalized in frows:
            table=pq.read_table(normalized["normalized_output_locator"],columns=["market_event_time_us","quote_volume"])
            positive_times.extend(int(x["market_event_time_us"]) for x in table.to_pylist()
                                  if float(x["quote_volume"]) > 0.0)
        current=[x for x in mapped if x["perp_symbol"]==symbol]
        map_row=row
        onboard_ms=map_row.get("onboardDate_metadata_ms")
        delivery_ms=map_row.get("deliveryDate_metadata_ms")
        # Binance uses a far-future delivery sentinel for active perpetuals.
        delivery_real_ms=(delivery_ms if isinstance(delivery_ms,int) and delivery_ms < 4_000_000_000_000 else None)
        first_raw=min(x["first_market_event_time_us"] for x in frows if x["first_market_event_time_us"])
        last_raw=max(x["last_market_event_time_us"] for x in frows if x["last_market_event_time_us"])
        onboard_us=onboard_ms*1000 if isinstance(onboard_ms,int) else None
        listing_candidates=[x for x in (onboard_us,first_raw) if x is not None]
        earliest_listing=min(listing_candidates)
        pit_eligibility_start=max(listing_candidates)
        source_disagreement=bool(onboard_us is not None and onboard_us != first_raw)
        status=map_row.get("futures_status")
        delisting_evidence=("CURRENT_METADATA_DELIVERY_DATE" if delivery_real_ms is not None and status=="SETTLING"
                            else "NO_AUTHORITATIVE_DELISTING_TIME; ARCHIVE_COVERAGE_RETAINED")
        episodes.append({"instrument_identity":{"venue":"BINANCE","family":"USD_M_PERPETUAL","symbol":symbol},
                         "episode_id":f"BINANCE-USD_M_PERPETUAL-{symbol}-L{onboard_ms if onboard_ms is not None else 'RAW'}",
                         "earliest_candidate_listing_us":earliest_listing,
                         "pit_eligibility_conservative_start_us":pit_eligibility_start,
                         "earliest_verified_raw_time_us":first_raw,
                         "latest_archive_observation_us":last_raw,
                         "latest_positive_transacted_observation_us":max(positive_times) if positive_times else None,
                         "archive_observation_boundary_semantics":"OFFICIAL_ARCHIVE_COVERAGE; MAY_INCLUDE_ZERO_VOLUME_PLACEHOLDER_BARS",
                         "onboardDate_metadata_us":onboard_us,"metadata_retrieved_at":plan["generated_at"],
                         "archive_months_present":[x["month"] for x in frows],
                         "archive_months_missing":[g["month"] for g in plan["source_archive_gaps"] if g["symbol"]==symbol and g["dataset"]=="futures_1h"],
                         "spot_availability":bool(current),"current_metadata_status":status,
                         "deliveryDate_metadata_us":delivery_real_ms*1000 if delivery_real_ms is not None else None,
                         "delisting_evidence":delisting_evidence,
                         "relisting_evidence":"NO_SEPARATE_EPISODE_PROVEN; CONFLICTS_PRESERVED_IF_DISCOVERED",
                         "disagreement_state":"SOURCE_DISAGREEMENT" if source_disagreement else "NO_OBSERVED_DISAGREEMENT",
                         "boundary_status":"CONSERVATIVE_RAW_OBSERVATION_BOUNDARY"})
    listing_path,listing_sha=artifact(root,out_dir,"P5_P3_LISTING_EPISODE_LEDGER_V1",
                                      {"generated_at":now_iso(),"episodes":episodes})

    executable=[]
    for cell in plan["executable_cells"]:
        keyset=[(d,cell["symbol"],cell["month"]) for d in ("futures_1h","spot_1h","funding")]
        if all(k in norm_idx for k in keyset): executable.append({"symbol":cell["symbol"],"month":cell["month"],
            "normalized_revision_hashes":{d:norm_idx[(d,cell["symbol"],cell["month"])]["normalized_output_sha256"]
                                          for d in ("futures_1h","spot_1h","funding")}})
    coverage_by_symbol=defaultdict(list)
    for c in executable: coverage_by_symbol[c["symbol"]].append(c["month"])
    complete_wave1=[s for s,months in coverage_by_symbol.items() if all(m in months for m in month_range(START_MONTH,"2025-06"))]
    complete_t1=[s for s,months in coverage_by_symbol.items() if all(m in months for m in month_range(START_MONTH,plan["engineering_max_available_month"]))]

    lineage_rows=[]
    for obj in plan["objects"]:
        rev=latest[obj["key"]]; norm=norm_idx.get((obj["dataset"],obj["symbol"],obj["month"]))
        row={k:rev.get(k) for k in ("revision_id","parent_revision_id","source_provider","source_namespace",
            "remote_object_identity","request_identity","retrieval_timestamp","source_published_at","official_checksum_sha256",
            "raw_sha256","raw_byte_size","raw_storage_locator","checksum_status")}
        if norm:
            row |= {"normalization_status":"NORMALIZED",
                "transform_code_identity":norm["transform_code_identity"],"transform_code_sha256":norm["transform_code_sha256"],
                "normalized_output_locator":norm["normalized_output_locator"],"normalized_output_sha256":norm["normalized_output_sha256"]}
        else:
            conflict=conflicts.get(obj["key"])
            if not conflict: raise RuntimeError(f"NORMALIZATION_MISSING_WITHOUT_CONFLICT:{obj['key']}")
            row |= {"normalization_status":"EXCLUDED_SOURCE_ARCHIVE_CONFLICT","conflict":conflict,
                    "transform_code_identity":None,"transform_code_sha256":None,
                    "normalized_output_locator":None,"normalized_output_sha256":None}
        lineage_rows.append(row)
    lineage_path,lineage_sha=artifact(root,out_dir,"P5_PC6_DATA_REVISION_LINEAGE_V3",
                                      {"generated_at":now_iso(),"revision_count":len(lineage_rows),"revisions":lineage_rows})

    qa={"generated_at":now_iso(),"raw_archive_objects":len(plan["objects"]),
        "raw_archive_bytes":sum(latest[x["key"]]["raw_byte_size"] for x in plan["objects"]),
        "checksum_failures":0,"archive_gaps":len(plan["source_archive_gaps"]),
        "identity_mapping_blocked_instruments":sum(x["status"] not in ("VERIFIED_UNIT_COMPATIBLE","VERIFIED_WITH_NORMALIZATION") for x in identity_rows),
        "unit_mapping_blocked_instruments":sum(x["status"]=="UNRESOLVED_UNIT_MAPPING" for x in identity_rows),
        "normalized_objects":len(norms),"normalized_rows":sum(x["row_count"] for x in norms),
        "executable_symbol_month_cells":len(executable),"wave1_complete_symbols":complete_wave1,
        "t1_engineering_window_complete_symbols":complete_t1,
        "duplicate_keys":sum("DUPLICATE_KEYS" in x.get("error","") for x in conflicts.values()),
        "normalization_failures":0,"source_archive_conflicts":list(conflicts.values()),
        "source_archive_gaps":plan["source_archive_gaps"]}
    qa_path,qa_sha=artifact(root,out_dir,"P5_PC6_BINANCE_STRUCTURAL_QA_V1",qa)

    inputs_hash=sha_bytes(canonical_bytes(sorted((x["raw_sha256"] for x in lineage_rows))))
    normalized_hash=sha_bytes(canonical_bytes(sorted((x["normalized_output_sha256"] for x in lineage_rows if x["normalized_output_sha256"]))))
    view_a={"holding_semantics":"FIXED_COMMON_CLOCK_8H","timestamp_unit":"epoch_us",
            "implementation":"binance_materializer.fixed_common_clock_8h_us",
            "interval":"[t,t+8h)","anchor_rule":"FULL_UTC_HOUR_GRID_FAIL_CLOSED",
            "decision_input":"PREVIOUS_FULLY_CLOSED_1H_BAR","funding_membership":"ALL_MARKET_EVENT_TIME_IN_[t,t+8h)",
            "input_raw_manifest_hash":inputs_hash,"normalized_manifest_hash":normalized_hash,"build_code_identity":build_code_identity}
    view_a["view_specification_hash_scope"]="CANONICAL_JSON_EXCLUDING_THIS_HASH_FIELD"
    view_a["view_specification_hash"]=sha_bytes(canonical_bytes(view_a))
    view_b={"holding_semantics":"ACTUAL_SETTLEMENT_TO_SETTLEMENT","timestamp_unit":"epoch_us",
            "implementation":"binance_materializer.actual_settlement_to_settlement_us",
            "interval":"[event_i,event_i+1)","realized_event_membership":"LEFT_EVENT_IN_OWN_HALF_OPEN_INTERVAL",
            "right_censoring":"FINAL_EVENT_HAS_NO_INVENTED_END_TIME",
            "duration_rule":{"raw_duration":"PRESERVED","snapped_interval_hours":"OFFICIAL_FUNDING_INTERVAL_HOURS",
                             "snap_tolerance_us":SNAP_TOLERANCE_US,"excess":"FAIL_CLOSED"},
            "fields":["start_us","end_us","raw_duration_us","snapped_interval_hours","realized_funding_events"],
            "decision_input":"PREVIOUS_FULLY_CLOSED_1H_BAR","input_raw_manifest_hash":inputs_hash,
            "normalized_manifest_hash":normalized_hash,"build_code_identity":build_code_identity}
    view_b["view_specification_hash_scope"]="CANONICAL_JSON_EXCLUDING_THIS_HASH_FIELD"
    view_b["view_specification_hash"]=sha_bytes(canonical_bytes(view_b))
    views_path,views_sha=artifact(root,out_dir,"P5_PC6_PRECOMPUTABLE_STRUCTURAL_VIEWS_V1",
                                  {"generated_at":now_iso(),"VIEW_A":view_a,"VIEW_B":view_b})

    h0_ready=bool(executable and complete_wave1)
    t1_ready=bool(executable and complete_t1)
    ready=bool(h0_ready or t1_ready)
