def main() -> int:
    ap=argparse.ArgumentParser(); ap.add_argument("command",choices=["enumerate","download","normalize","artifacts","all"])
    ap.add_argument("--root",type=Path,required=True); ap.add_argument("--artifacts",type=Path)
    ap.add_argument("--workers",type=int,default=24); args=ap.parse_args()
    args.root.mkdir(parents=True,exist_ok=True)
    lock_path=args.root/".materializer.lock"
    with lock_path.open("a+b") as lock:
        try: fcntl.flock(lock.fileno(),fcntl.LOCK_EX|fcntl.LOCK_NB)
        except BlockingIOError as e: raise RuntimeError(f"MATERIALIZER_ALREADY_RUNNING:{args.root}") from e
        if args.command in ("enumerate","all"): enumerate_plan(args.root,args.workers)
        if args.command in ("download","all"): download_plan(args.root,args.workers)
        if args.command in ("normalize","all"): normalize_all(args.root,Path(__file__),args.workers)
        if args.command in ("artifacts","all"):
            if not args.artifacts: ap.error("--artifacts required")
            args.artifacts.mkdir(parents=True,exist_ok=True); build_artifacts(args.root,args.artifacts,Path(__file__))
    return 0


