GRID_STEP_HOURS = 8
GRID_STEP_US = GRID_STEP_HOURS * US_PER_HOUR
ALLOWED_UTC_SLOT_HOURS = (0, 8, 16)

# Frozen prereg V3 section 8 constants (never client-supplied).
T1_GRID_START_UTC = "2023-07-02T00:00:00Z"
T1_GRID_END_UTC = "2026-07-31T16:00:00Z"
