T1_FROZEN_CUTOFF = "2026-07-31T23:59:59.999Z"
T1_FROZEN_CUTOFF_EPOCH_US = 1785542399999000

# Frozen W1 contract section 8 constants.
W1_DEV_LABEL_BOUNDARY_UTC = "2025-07-01T00:00:00Z"
W1_LAST_DECISION_UTC = {
